import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";
import * as schema from "./schema.js";

/** Any drizzle Postgres database over our schema: postgres-js in the app, PGlite in tests. */
export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

/** Folder of SQL migrations generated by `npm run db:generate`. */
export const MIGRATIONS_FOLDER = new URL("../../drizzle", import.meta.url).pathname;

/** Connects to Postgres and applies pending migrations. */
export async function connectDb(url: string): Promise<Db> {
  const db = drizzle(postgres(url), { schema });
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  return db;
}
